#!/usr/bin/env python3
"""soapff paper: OVITO renderings of the quartz (101), albite (001), brucite (001) and pyrophyllite (001) systems as generated by soapff (types from
system.data), side view.  Run with the OVITO Python environment."""
import os
import numpy as np
import matplotlib
matplotlib.use("Agg")
import matplotlib.pyplot as plt
from matplotlib.colors import to_rgb
from matplotlib.lines import Line2D
from ovito.io import import_file
from ovito.modifiers import CreateBondsModifier
from ovito.vis import TachyonRenderer, Viewport
HERE = os.path.dirname(os.path.abspath(__file__))
EX = "/private/tmp/claude-501/-Users-harutokono-ScoreMD/64bceb4c-942b-429c-8731-e59ed7d791ef/scratchpad/clayff_eval/out"
COL = {"st": "#e8c547", "at": "#c07ad8", "ao": "#8e5bb5", "mgh": "#3fa34d", "ob": "#d9412b", "obts": "#8a2b1a", "oh": "#f08c3c", "ho": "#9a9a9a", "Na": "#3f6fd8", "ow": "#7fb2e0", "hw": "#cfe3f3"}
RAD = {"st": 0.42, "at": 0.45, "ao": 0.45, "mgh": 0.45, "ob": 0.36, "obts": 0.38, "oh": 0.36, "ho": 0.2, "Na": 0.7, "ow": 0.34, "hw": 0.17}
NAME = {"st": "st (Si)", "at": "at (Al(IV))", "ao": "ao (Al(VI))", "mgh": "mgh (Mg)", "ob": "ob (Si-O-Si)", "obts": "obts (Si-O-Al(IV))", "oh": "oh (OH)", "ho": "ho (H of OH)",
        "Na": "Na+", "ow": "ow (water O)", "hw": "hw (water H)"}
plt.rcParams.update({"font.family": "Hiragino Sans"})
fig, axs = plt.subplots(1, 4, figsize=(22, 7.5))
for ax, name, title in zip(axs, ("quartz_0", "albite_0", "brucite_0", "pyrophyllite_0"),
                          ("(a) 石英", "(b) アルバイト", "(c) ブルーサイト", "(d) パイロフィライト")):
    p = import_file(os.path.join(EX, name, "system.data"), atom_style="full")
    data = p.source.data
    data.cell_.vis.enabled = False
    present = []
    for t in data.particles_.particle_types_.types_:
        if t.name in COL:
            t.color = to_rgb(COL[t.name]); t.radius = RAD[t.name]; present.append(t.name)
    b = CreateBondsModifier(mode=CreateBondsModifier.Mode.Pairwise)
    for m, c in (("st", 2.0), ("at", 2.0), ("ao", 2.2), ("mgh", 2.3)):
        for o in ("ob", "obts", "oh"):
            b.set_pairwise_cutoff(m, o, c)
    b.vis.width = 0.22
    p.modifiers.append(b)
    p.add_to_scene()
    cell = np.array(data.cell[:, :3])
    c = cell.sum(0) / 2
    vp = Viewport(type=Viewport.Type.Ortho, camera_pos=(c[0], -80, c[2]), camera_dir=(0, 1, 0), fov=float(max(cell[2, 2], cell[0, 0])) / 2 + 1)
    path = os.path.join(HERE, "figs", f"_{name}.png")
    vp.render_image(size=(1100, 1100), filename=path, background=(1, 1, 1), renderer=TachyonRenderer(ambient_occlusion=True))
    p.remove_from_scene()
    ax.imshow(plt.imread(path)); ax.axis("off"); ax.set_title(title, loc="left", fontsize=13)
    ax.legend(handles=[Line2D([], [], marker="o", ls="", color=COL[t], markeredgecolor="#333", markersize=8, label=NAME[t])
                       for t in COL if t in present], fontsize=9, loc="upper center", bbox_to_anchor=(0.5, -0.0), ncol=3, frameon=False)
    os.remove(path)
fig.tight_layout(); fig.savefig(os.path.join(HERE, "figs", "minerals.png"), dpi=150, bbox_inches="tight")
print("ok")
